function currentView(){return location.hash.slice(1)||"dashboard"}function render(view=currentView()){if(!state.user)return;const fn={dashboard:renderDashboard,calendar:renderCalendar,students:renderStudents,teachers:renderTeachers,forms:renderStudentForms,templates:renderTemplates,makeup:renderMakeup,reports:renderReports,notes:renderNotes,history:renderHistory,settings:renderSettings}[view]||renderDashboard;fn()}
const empty=(title,text)=>`<div class="empty"><strong>${title}</strong>${text}</div>`;
