function sessionRow(s){const st=student(s.studentId),tc=teacher(s.teacherId),ui=sessionUi(s);return `<button type="button" class="session-card ${ui.status}" data-session="${escapeHtml(s.id)}" data-teacher="${escapeHtml(s.teacherId||"")}" style="--student:${safeColor(tc.color,"#94a3b8")}"><strong>${escapeHtml(st.shortName||st.fullName)}</strong><small>${ui.startTime}–${ui.endTime} · ${STATUS[ui.status]}</small><small>♟ ${escapeHtml(tc.shortName||tc.fullName)}</small></button>`}
