  bindWeekControls();if(sessionsLoaded){bindSessionClicks();bindCalendarAdds()}
  const dayDetails=[...document.querySelectorAll("details.day-column")];if(matchMedia("(max-width: 760px)").matches&&dayDetails.length){const preferred=dayDetails.find(x=>x.dataset.dayDate===isoDate(new Date()))||dayDetails[0];dayDetails.forEach(x=>x.open=x===preferred)}
