  const teacherIds=[...new Set(ordered.map(record=>record.teacherId||"__unassigned"))].sort((a,b)=>(teacher(a==="__unassigned"?"":a).fullName||"").localeCompare(teacher(b==="__unassigned"?"":b).fullName||"","vi"));
