function renderMakeup(){const needs=state.students.filter(s=>s.active&&Number(s.makeupBalance)>0).sort((a,b)=>b.makeupBalance-a.makeupBalance);$("#content").innerHTML=`<div class="grid section-grid"><section class="card"><div class="section-head"><div><h2>Danh sách cần học bù</h2><p class="muted">Sắp xếp theo số buổi còn thiếu.</p></div></div><div class="makeup-list">${needs.length?needs.map(s=>`<div class="makeup-chip" style="--student:${safeColor(s.color,"#94a3b8")}"><span><strong>${escapeHtml(s.fullName)}</strong><small>${escapeHtml(s.note||"Đang chờ xếp lịch")}</small></span><span class="badge warning">${s.makeupBalance} buổi</span></div>`).join(""):empty("Không còn buổi cần bù","Tất cả học sinh đã được cân bằng.")}</div></section><section class="card"><div class="section-head"><h2>Nguyên tắc số dư</h2></div><div class="notice info">Xin nghỉ hợp lệ cộng 1. Chỉ khi hoàn thành buổi học bù mới trừ 1. Xóa giao dịch sẽ tự điều chỉnh lại số dư.</div><div class="timeline" style="margin-top:15px">${state.transactions.slice(0,20).map(transactionItem).join("")||empty("Chưa có giao dịch","Giao dịch nghỉ/bù sẽ xuất hiện ở đây.")}</div></section></div>`;document.querySelectorAll(".delete-transaction").forEach(b=>b.onclick=async()=>{const t=state.transactions.find(x=>x.id===b.dataset.id);if(!confirm(`Xóa giao dịch ${t.quantity>0?"+":""}${t.quantity} buổi? Số dư học sinh sẽ được tính lại.`))return;try{await deleteMakeupTransaction(t,state.user);toast("Đã xóa giao dịch và cập nhật số dư.")}catch(e){toast(e.message,"error")}})}
function transactionItem(t){const s=student(t.studentId),quantity=Number(t.quantity)||0;return `<div class="timeline-item"><span><strong>${escapeHtml(s.shortName||s.fullName)} · ${quantity>0?"+":""}${quantity} buổi</strong><small>${escapeHtml(t.reason||t.type)} · ${t.createdAt?localDate(t.createdAt):"vừa cập nhật"}</small></span>${isOwner()?`<button class="icon-button danger delete-transaction" data-id="${escapeHtml(t.id)}" title="Xóa giao dịch" aria-label="Xóa giao dịch">🗑</button>`:""}</div>`}
const sessionMinutes=s=>{const parse=value=>{const [h,m]=String(value||"").split(":").map(Number);return Number.isFinite(h)&&Number.isFinite(m)?h*60+m:NaN},minutes=parse(s.endTime)-parse(s.startTime);return minutes>0&&minutes<=720?minutes:0};
const formatHours=minutes=>{const value=Math.round((Number(minutes||0)/60)*10)/10;return `${Number.isInteger(value)?value:value.toFixed(1)} giờ`};
function reportRows(sessions){
  const completed=new Set(["attended","makeup_completed"]),studentIds=new Set([...state.students.map(x=>x.id),...sessions.map(x=>x.studentId).filter(Boolean)]),studentStats=[...studentIds].map(id=>{const person=student(id),own=sessions.filter(x=>x.studentId===id),planned=own.filter(x=>x.status!=="cancelled").reduce((sum,x)=>sum+sessionMinutes(x),0),learned=own.filter(x=>completed.has(x.status)).reduce((sum,x)=>sum+sessionMinutes(x),0);return {id,person,planned,learned,balance:Number(person.makeupBalance||0)}}).sort((a,b)=>(a.person.fullName||"").localeCompare(b.person.fullName||"","vi"));
  const slots=new Map();sessions.filter(x=>x.teacherId&&x.status!=="cancelled").forEach(x=>{const key=`${x.teacherId}|${x.dateKey}|${x.startTime}|${x.endTime}`,slot=slots.get(key)||{teacherId:x.teacherId,minutes:sessionMinutes(x),taught:false};slot.taught ||= completed.has(x.status);slots.set(key,slot)});const teacherIds=new Set([...state.teachers.map(x=>x.id),...[...slots.values()].map(x=>x.teacherId)]),teacherStats=[...teacherIds].map(id=>{const person=teacher(id),own=[...slots.values()].filter(x=>x.teacherId===id);return {id,person,planned:own.reduce((sum,x)=>sum+x.minutes,0),taught:own.filter(x=>x.taught).reduce((sum,x)=>sum+x.minutes,0),slots:own.length}}).sort((a,b)=>(a.person.fullName||"").localeCompare(b.person.fullName||"","vi"));return {studentStats,teacherStats}
}
