  const titleInput=$("#dialogForm [name='formTitle']"),startInput=$("#dialogForm [name='courseStart']"),endInput=$("#dialogForm [name='courseEnd']"),periodInput=$("#dialogForm [name='coursePeriod']"),teacherInput=$("#dialogForm [name='teacherId']"),orderInput=$("#dialogForm [name='displayOrder']"),hint=$("#formPeriodHint");
  const showPeriodHint=()=>{const hasTitle=Boolean(titleInput.value.trim()),hasPeriod=Boolean(periodInput.value),invalidYear=formHasInvalidYear({formTitle:titleInput.value});hint.className=`notice ${hasPeriod&&!invalidYear?"info":"form-period-warning"}`;if(manualOverride){hint.innerHTML=hasPeriod?(invalidYear?`⚠ Tiêu đề có năm không hợp lệ; đang giữ thời gian nhập thủ công: <strong>${escapeHtml(periodInput.value)}</strong>.`: `✓ Đang giữ thời gian nhập thủ công: <strong>${escapeHtml(periodInput.value)}</strong>.`):"⚠ Thời gian thủ công chưa đủ. Hãy nhập cả hai ô Từ và Đến.";return}hint.innerHTML=invalidYear?(hasPeriod?`⚠ Năm trong tiêu đề không hợp lệ. Đang tạm giữ ngày/tháng: <strong>${escapeHtml(periodInput.value)}</strong>. Hãy sửa tiêu đề hoặc xác nhận bằng cách nhập lại hai ô Từ/Đến.`:"⚠ Năm trong tiêu đề không hợp lệ. Thời gian tự động đã được xóa; hãy sửa tiêu đề hoặc nhập thủ công."):hasPeriod?`✓ Đã nhận thời gian từ tiêu đề: <strong>${escapeHtml(periodInput.value)}</strong>`:autoPeriodCleared?"⚠ Tiêu đề mới không có khoảng ngày. Thời gian tự động cũ đã được xóa.":hasTitle?"⚠ Không tìm thấy khoảng thời gian trong tiêu đề. Bạn có thể nhập hai ô Từ/Đến.":"Nhập tiêu đề Form để tự điền thời gian, hoặc nhập hai ô Từ/Đến."};
