function openTemplateForm(t={}){
  const students=state.students.filter(s=>s.active||s.id===t.studentId),teachers=state.teachers.filter(x=>x.active||x.id===t.teacherId);if(!students.length)return toast("Hãy thêm học sinh đang học trước.","error");if(!teachers.length)return toast("Hãy thêm ít nhất một giáo viên đang dạy trước.","error");
  dialog(t.id?"Sửa lịch mẫu":"Thêm lịch mẫu",`<div class="form-grid"><label>Học sinh *<select name="studentId" required>${students.map(s=>`<option value="${escapeHtml(s.id)}" ${t.studentId===s.id?"selected":""}>${escapeHtml(s.fullName)}</option>`).join("")}</select></label><label>Giáo viên *<select name="teacherId" required>${teachers.map(x=>`<option value="${escapeHtml(x.id)}" ${t.teacherId===x.id?"selected":""}>${escapeHtml(x.fullName)}</option>`).join("")}</select></label><label>Thứ<select name="dayOfWeek">${DAYS.map((d,i)=>`<option value="${i}" ${Number(t.dayOfWeek)===i?"selected":""}>${d}</option>`).join("")}</select></label><label>Số chỗ của lịch này<input name="capacity" type="number" min="1" max="20" value="${safeCapacity(t.capacity)}"><small class="field-help">Mặc định 1; các lịch thường cùng giờ sẽ được cộng lại.</small></label><label>Giờ bắt đầu<input name="startTime" type="time" required value="${safeTime(t.startTime,"13:00")}"></label><label>Giờ kết thúc<input name="endTime" type="time" required value="${safeTime(t.endTime,"14:00")}"></label></div><label>Ghi chú<textarea name="note">${escapeHtml(t.note||"")}</textarea></label><label>Trạng thái<select name="active"><option value="true" ${t.active!==false?"selected":""}>Đang sử dụng</option><option value="false" ${t.active===false?"selected":""}>Tạm dừng</option></select></label>`,async fd=>{const data=Object.fromEntries(fd),active=data.active==="true",capacity=Number(data.capacity||1),day=Number(data.dayOfWeek),others=state.templates.filter(x=>x.id!==t.id&&x.active&&Number(x.dayOfWeek)===day);if(!TIME_PATTERN.test(data.startTime)||!TIME_PATTERN.test(data.endTime)||data.startTime>=data.endTime)throw new Error("Giờ kết thúc phải sau giờ bắt đầu.");if(!Number.isInteger(capacity)||capacity<1||capacity>20)throw new Error("Số chỗ của mỗi lịch phải từ 1 đến 20 học sinh.");if(active&&others.some(x=>x.studentId===data.studentId&&safeTime(x.startTime,"")<data.endTime&&data.startTime<safeTime(x.endTime,"")))throw new Error("Học sinh đã có lịch mẫu trùng giờ.");if(active&&others.some(x=>x.teacherId===data.teacherId&&safeTime(x.startTime,"")<data.endTime&&data.startTime<safeTime(x.endTime,"")&&!(x.startTime===data.startTime&&x.endTime===data.endTime)))throw new Error("Giáo viên đã có lịch mẫu khác trùng giờ.");return saveTemplate({...data,capacity,active},state.user,t.id)})
}
function openSessionForm(s={}){const w=activeWeek(),ui=sessionUi(s),students=state.students.filter(x=>x.active||x.id===s.studentId),teachers=state.teachers.filter(x=>x.active||x.id===s.teacherId);if(!w)return openWeekForm();if(!students.length)return toast("Hãy thêm ít nhất một học sinh đang học.","error");if(!teachers.length)return toast("Hãy thêm ít nhất một giáo viên đang dạy.","error");if(s.id&&["absent","makeup_completed"].includes(ui.status))return toast("Hãy hoàn tác trạng thái nghỉ/đã bù trước khi đổi học sinh hoặc giờ.","error");const dateKey=/^\d{4}-\d{2}-\d{2}$/.test(String(s.dateKey||""))?String(s.dateKey):isoDate(w.startDate.toDate());dialog(s.id?"Sửa buổi học":"Thêm buổi học",`<div class="form-grid"><label>Ngày học *<input name="dateKey" type="date" required min="${isoDate(w.startDate.toDate())}" max="${isoDate(w.endDate.toDate())}" value="${dateKey}"></label><label>Học sinh *<select name="studentId" required>${students.map(x=>`<option value="${escapeHtml(x.id)}" ${s.studentId===x.id?"selected":""}>${escapeHtml(x.fullName)}</option>`).join("")}</select></label><label>Giáo viên *<select name="teacherId" required>${teachers.map(x=>`<option value="${escapeHtml(x.id)}" ${(s.teacherId||"")===x.id?"selected":""}>${escapeHtml(x.fullName)}</option>`).join("")}</select></label><label>Loại buổi<select name="type" ${s.id?"disabled":""}><option value="regular" ${ui.type!=="makeup"?"selected":""}>Lịch thường</option><option value="makeup" ${ui.type==="makeup"?"selected":""}>Học bù</option></select></label><label>Giờ bắt đầu *<input name="startTime" type="time" required value="${safeTime(s.startTime,"13:00")}"></label><label>Giờ kết thúc *<input name="endTime" type="time" required value="${safeTime(s.endTime,"14:00")}"></label><label>Số chỗ của lịch này<input name="capacity" type="number" min="1" max="20" value="${safeCapacity(s.capacity)}"><small class="field-help">Lịch thường mặc định 1; buổi học bù không cộng thêm sức chứa.</small></label></div><label>Ghi chú<textarea name="note">${escapeHtml(s.note||"")}</textarea></label>`,async fd=>{const data=Object.fromEntries(fd);if(s.id)data.type=ui.type;const date=new Date(`${data.dateKey}T12:00:00`),start=w.startDate.toDate(),end=w.endDate.toDate();if(date<start||date>end)throw new Error("Ngày học phải nằm trong tuần đang chọn.");if(!TIME_PATTERN.test(data.startTime)||!TIME_PATTERN.test(data.endTime)||data.startTime>=data.endTime)throw new Error("Giờ kết thúc phải sau giờ bắt đầu.");data.dayOfWeek=Math.round((date-start)/86400000);data.status=s.id?ui.status:(data.type==="makeup"?"makeup_scheduled":"scheduled");await saveSession(state.weekId,data,state.sessions,state.user,s.id)})}
function mondayFor(date){const d=new Date(date),day=d.getDay(),offset=day===0?-6:1-day;return isoDate(addDays(d,offset))}
function openWeekForm(){const next=(Math.max(0,...state.weeks.map(w=>Number(w.weekNumber)||0))+1),monday=mondayFor(new Date()),validTemplates=state.templates.filter(t=>t.active&&state.students.some(s=>s.id===t.studentId&&s.active)&&state.teachers.some(x=>x.id===t.teacherId&&x.active)),ignored=state.templates.filter(t=>t.active).length-validTemplates.length;dialog("Tạo tuần mới",`<div class="notice info">${validTemplates.length?`${validTemplates.length} lịch mẫu hợp lệ sẽ được sao chép sang tuần mới.${ignored?` Bỏ qua ${ignored} lịch thiếu học sinh/giáo viên hoạt động.`:""}`:"Chưa có lịch mẫu hợp lệ. Tuần mới vẫn được tạo để bạn click từng ngày và thêm buổi."}</div><div class="form-grid"><label>Số tuần<input name="weekNumber" type="number" min="1" required value="${next}"></label><label>Thứ Hai bắt đầu tuần<input name="startDate" type="date" required value="${monday}"></label></div>`,async fd=>{const data=Object.fromEntries(fd),date=new Date(`${data.startDate}T12:00:00`);if(date.getDay()!==1)throw new Error("Ngày bắt đầu tuần phải là Thứ Hai.");if(!navigator.onLine)throw new Error("Thiết bị đang ngoại tuyến.");const id=await createWeek(data,validTemplates,state.weeks,state.user);selectWeek(id);location.hash="calendar"})}

